mapper.select:
select cm16.*, cm15.cm15_code as cm16_stok, cm15.cm15_name from tb_cm_16 cm16 left join tb_cm_15 cm15 on cm15.cm15_company = cm16.cm16_company and cm15.cm15_factory = cm16.cm16_factory and cm15.cm15_code = cm16.cm16_stok where 1 = 1 and cm16_company = #{company} and cm16_factory = #{factory}
and cm16_stok LIKE CONCAT ('%',#{cm16Stok},'%')
and cm16_code LIKE CONCAT ('%',#{cm16Code},'%')
and cm16_name LIKE CONCAT ('%',#{cm16Name},'%')
and cm16_lock = #{cm16Lock}

select cm16.*,
       cm15.cm15_name
from tb_cm_16 cm16
left join tb_cm_15 cm15
    on cm15.cm15_company = cm16.cm16_company
    and cm15.cm15_factory = cm16.cm16_factory
    and cm15.cm15_code = cm16.cm16_stok
where 1 = 1
    and cm16_company = #{company}
    and cm16_factory = #{factory}
    and cm16_stok = #{cm16Stok}
    and cm16_code = #{cm16Code}

mapper.update:
update tb_cm_16
set
    cm16_name = #{cm16Name},
    cm16_lock = #{cm16Lock},
    cm16_rmk = #{cm16Rmk},
    cm16_updte = sysdate,
    cm16_empno = #{cm16Empno}
where 1 = 1
    and cm16_company = #{company}
    and cm16_factory = #{factory}
    and cm16_stok = #{cm16Stok}
    and cm16_code = #{cm16Code}

